const u = $input.first().json;
const m = u.message || u.edited_message || null;
if (!m || !m.chat || !m.from) return [{ json: { action: 'ignore', reason: 'unsupported_update', update_id: u.update_id ?? null } }];
const updateId = Number(u.update_id);
if (!Number.isInteger(updateId)) throw new Error('Telegram Trigger payload is missing a valid update_id');
const ignore = m.from.is_bot === true || m.chat.type !== 'private' || typeof m.text !== 'string' || !m.text.trim();
return [{ json: { action: ignore ? 'ignore' : 'process', reason: ignore ? 'bot_group_or_non_text' : null, update_id: updateId, message: ignore ? null : m } }];

const it = $('Normalize Webhook Update').first().json;
const m = it.message;
const from = m.from || {};
const chat = m.chat;
return [{ json: {
  update_id: it.update_id,
  message_id: m.message_id,
  chat_id: chat.id,
  user_id: from.id,
  username: from.username || null,
  first_name: from.first_name || null,
  last_name: from.last_name || null,
  message_text: String(m.text || '').trim().slice(0, 4000),
  message_timestamp: m.date ? new Date(m.date * 1000).toISOString() : new Date().toISOString(),
  conversation_key: 'telegram:' + chat.id,
  source: 'telegram'
} }];

const n = $('Normalize Message').first().json;
const ctx = $('Get Conversation History').first().json;
const kb = $('Get Belghamdi Knowledge Base').first().json;
const strip = (s) => String(s ?? '').replace(/<\/?[a-z_]+>/gi, '').trim();
const latin = (s) => String(s).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const items = Array.isArray(kb.items) ? kb.items : [];
if (!items.length) throw new Error('Knowledge base is empty');
const kbText = items.map(i => '[' + i.category + '] ' + i.title + '\n' + i.content).join('\n\n');
const allowed = new Set();
(latin(kbText).replace(/(\d),(\d)/g, '$1$2').match(/\d+/g) || []).forEach(x => { if (Number(x) >= 100) allowed.add(Number(x)); });
const history = (Array.isArray(ctx.history) ? ctx.history : [])
  .map(h => (h.role === 'assistant' ? 'ASSISTANT: ' : 'CUSTOMER: ') + strip(h.content).slice(0, 1500)).join('\n');
const tgName = [n.first_name, n.last_name].filter(Boolean).join(' ');
const nowCairo = new Date().toLocaleString('en-GB', { timeZone: 'Africa/Cairo' });
const agent_input = [
  '<knowledge_base>', kbText, '</knowledge_base>',
  '<existing_lead_profile>', JSON.stringify(ctx.lead || null), '</existing_lead_profile>',
  '<telegram_profile>', 'display_name (unverified): ' + (strip(tgName) || 'unknown'), 'new_conversation: ' + (ctx.is_new_conversation === true), 'current_time_cairo: ' + nowCairo, '</telegram_profile>',
  '<conversation_history>', history || '(no previous messages)', '</conversation_history>',
  '<new_customer_message>', strip(n.message_text).slice(0, 2000), '</new_customer_message>'
].join('\n');
return [{ json: { agent_input, conversation_id: ctx.conversation_id, allowed_numbers: [...allowed], existing_lead: ctx.lead || null } }];

const clean = (s) => String(s ?? '')
  .replace(/bot\d{6,}:[A-Za-z0-9_-]{20,}/g, 'bot***')
  .replace(/eyJ[A-Za-z0-9._-]{20,}/g, 'jwt***')
  .replace(/(apikey|api_key|token|authorization|bearer)["'=: ]+[A-Za-z0-9._-]{12,}/gi, '$1=***')
  .slice(0, 300);
const build = $('Build AI Context').first().json;
let o = $input.first().json.output;
if (o && typeof o === 'object' && o.output && typeof o.output === 'object') o = o.output;
if (typeof o === 'string') {
  try { o = JSON.parse(o.replace(/^```(?:json)?\s*|\s*```$/g, '').trim()); }
  catch (e) { throw new Error('AI output is not valid JSON'); }
}
if (!o || typeof o !== 'object' || Array.isArray(o)) throw new Error('AI output is not an object');

const INTENTS = ['greeting','package_inquiry','pricing_inquiry','fitness_goal','package_recommendation','subscription_interest','payment_inquiry','existing_client_support','general_question','human_handoff','other'];
const STATUSES = ['new','collecting_information','qualified','contacted','converted','lost'];
const latin = (s) => String(s).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const str = (v, max = 200) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  const l = s.toLowerCase();
  return s && l !== 'null' && l !== 'unknown' && l !== 'none' ? s.slice(0, max) : null;
};

const reply = typeof o.reply === 'string' ? o.reply.trim() : '';
if (!reply) throw new Error('AI output missing reply');

// Deterministic price guard: every price in the reply must exist in the knowledge base.
const allowed = new Set(build.allowed_numbers || []);
const norm = latin(reply).replace(/(\d)[,٬](\d)/g, '$1$2');
const bad = [];
const re = /(\d{3,6})\s*(?:جنيه|جنية|ج\.?\s?م|EGP|LE)|(?:EGP|LE)\s*(\d{3,6})/gi;
let m;
while ((m = re.exec(norm)) !== null) {
  const v = Number(m[1] || m[2]);
  if (!allowed.has(v)) bad.push(v);
}
if (bad.length) throw new Error('AI reply contains a price not found in the knowledge base: ' + bad.join(','));

const ld = (o.lead_data && typeof o.lead_data === 'object') ? o.lead_data : {};
let phone = null;
const phoneRaw = str(ld.phone, 40);
if (phoneRaw) {
  const p = latin(phoneRaw).replace(/[^\d+]/g, '');
  const digits = p.replace(/\D/g, '').length;
  if (digits >= 8 && digits <= 15) phone = p;
}
const emailRaw = str(ld.email, 120);
const email = emailRaw && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailRaw) ? emailRaw.toLowerCase() : null;
let pkg = str(ld.interested_package, 40);
if (pkg) { const l = pkg.toLowerCase(); pkg = l.includes('gold') || pkg.includes('جولد') ? 'gold' : (l.includes('silver') || pkg.includes('سيلفر') ? 'silver' : null); }

let score = parseInt(o.qualification_score, 10);
score = Number.isFinite(score) ? Math.min(100, Math.max(0, score)) : 0;
let conf = Number(o.confidence);
conf = Number.isFinite(conf) ? Math.min(1, Math.max(0, conf)) : 0;
const coerced = !INTENTS.includes(o.intent) || !STATUSES.includes(o.lead_status);

return [{ json: {
  reply: reply.slice(0, 3500),
  intent: INTENTS.includes(o.intent) ? o.intent : 'other',
  lead_status: STATUSES.includes(o.lead_status) ? o.lead_status : 'new',
  lead_data: {
    name: str(ld.name, 120), phone, email,
    fitness_goal: str(ld.fitness_goal), current_weight: str(ld.current_weight, 40), target_weight: str(ld.target_weight, 60),
    training_location: str(ld.training_location, 80), training_days: str(ld.training_days, 60),
    experience_level: str(ld.experience_level, 60), interested_package: pkg
  },
  qualification_score: score,
  qualified: o.qualified === true,
  contact_permission_granted: o.contact_permission_granted === true,
  handoff_required: o.handoff_required === true,
  missing_information: Array.isArray(o.missing_information) ? o.missing_information.map(x => str(x, 40)).filter(Boolean).slice(0, 6) : [],
  confidence: conf,
  coerced
} }];

const v = $('Validate Structured Output').first().json;
const n = $('Normalize Message').first().json;
const ctx = $('Build AI Context').first().json;
const ld = v.lead_data;
const ex = ctx.existing_lead || {};
const hasPackage = !!(ld.interested_package || ex.interested_package);
const hasGoal = !!(ld.fitness_goal || ex.fitness_goal);
const hasContact = !!(ld.phone || ld.email || ex.phone || ex.email);
const contactPermission = v.contact_permission_granted === true;
const NOT_LEAD_INTENTS = ['greeting', 'pricing_inquiry', 'general_question', 'other'];

// Qualification: the AI proposes, deterministic rules decide.
const genuineInterest = ['subscription_interest','package_recommendation'].includes(v.intent);
const qualified = v.qualified === true && genuineInterest && (hasPackage || hasGoal) && (hasContact || contactPermission);
const status = qualified ? 'qualified' : (v.lead_status === 'new' ? 'new' : 'collecting_information');
let score = v.qualification_score;
score = qualified ? Math.max(score, 60) : Math.min(score, 59);

const anyData = Object.values(ld).some(x => x !== null);
const INTEREST = ['fitness_goal', 'package_recommendation', 'subscription_interest', 'payment_inquiry', 'human_handoff', 'existing_client_support'];
const should_upsert = anyData || qualified || v.handoff_required || INTEREST.includes(v.intent) || status !== 'new';

return [{ json: {
  should_upsert, qualified, status,
  payload: {
    telegram_user_id: n.user_id, telegram_chat_id: n.chat_id, telegram_username: n.username,
    full_name: ld.name, phone: ld.phone, email: ld.email, fitness_goal: ld.fitness_goal,
    current_weight: ld.current_weight, target_weight: ld.target_weight, training_location: ld.training_location,
    training_days: ld.training_days, experience_level: ld.experience_level, interested_package: ld.interested_package,
    lead_status: status, qualification_score: score, qualified, handoff_required: v.handoff_required,
    conversation_id: ctx.conversation_id
  }
} }];

const r = $input.first().json;
const n = $('Normalize Message').first().json;
const cfg = $('Config').first().json;
const s = r.snapshot || {};
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cap = (t) => t ? String(t).charAt(0).toUpperCase() + String(t).slice(1) : null;
const label = (t) => String(t || '').split('_').map(cap).join(' ');
const tgName = [n.first_name, n.last_name].filter(Boolean).join(' ');
const name = s.full_name || (tgName ? tgName + ' (Telegram profile)' : 'Not provided');
const time = new Date().toLocaleString('en-GB', { timeZone: 'Africa/Cairo' });
const lines = [];
if (r.should_notify) lines.push('<b>NEW QUALIFIED LEAD</b>');
if (r.handoff_notify) lines.push('<b>HUMAN HANDOFF REQUESTED</b>');
lines.push('',
  'Name: ' + esc(name),
  'Telegram: ' + (n.username ? '@' + esc(n.username) : 'No username') + ' (<a href="tg://user?id=' + Number(n.user_id) + '">open chat</a>)',
  'Package Interest: ' + esc(cap(s.interested_package) || 'Not specified'),
  'Goal: ' + esc(s.fitness_goal || 'Not specified'),
  'Target: ' + esc(s.target_weight || 'Not specified'),
  'Training Days: ' + esc(s.training_days || 'Not specified'),
  'Contact Details Provided: ' + (s.has_contact ? 'Yes' : 'No'),
  'Status: ' + esc(label(r.lead_status)),
  'Source: Telegram AI Assistant',
  'Lead ID: ' + esc(r.lead_code),
  'Time (Cairo): ' + esc(time));
return [{ json: { chat_id: cfg.sales_chat_id, text: lines.join('\n'), lead_id: r.lead_id, notify_qualified: r.should_notify === true, notify_handoff: r.handoff_notify === true } }];

const clean = (s) => String(s ?? '')
  .replace(/bot\d{6,}:[A-Za-z0-9_-]{20,}/g, 'bot***')
  .replace(/eyJ[A-Za-z0-9._-]{20,}/g, 'jwt***')
  .replace(/(apikey|api_key|token|authorization|bearer)[\"'=: ]+[A-Za-z0-9._-]{12,}/gi, '$1=***')
  .slice(0, 300);
const prev = $('Build Sales Notification').first().json;
const r = $input.first().json || {};
// Native n8n Telegram node returns the sent Telegram message object on success.
const ok = !r.error && (r.message_id !== undefined || r.message !== undefined || r.ok === true);
return [{ json: {
  lead_id: prev.lead_id, qualified: prev.notify_qualified, handoff: prev.notify_handoff,
  success: ok, error: ok ? null : clean((r.error && (r.error.message || r.error.description)) || r.description || 'sales notification failed')
} }];

const reply = $('Validate Structured Output').first().json.reply;
const chatId = $('Normalize Message').first().json.chat_id;
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LIMIT = 3800; // Telegram max is 4096 characters after entity parsing; keep headroom
const pieces = [];
for (const line of String(reply).split('\n')) {
  if (esc(line).length <= LIMIT) { pieces.push(line); continue; }
  let cur = '';
  for (const word of line.split(' ')) {
    if (esc(word).length > LIMIT) {
      if (cur) { pieces.push(cur); cur = ''; }
      for (let i = 0; i < word.length; i += 1000) pieces.push(word.slice(i, i + 1000));
    } else if (esc(cur ? cur + ' ' + word : word).length > LIMIT) { pieces.push(cur); cur = word; }
    else cur = cur ? cur + ' ' + word : word;
  }
  if (cur) pieces.push(cur);
}
const chunks = [];
let buf = '';
for (const p of pieces) {
  const next = buf ? buf + '\n' + p : p;
  if (buf && esc(next).length > LIMIT) { chunks.push(buf); buf = p; } else buf = next;
}
if (buf.trim()) chunks.push(buf);
if (!chunks.length) throw new Error('Empty reply');
return chunks.map((c, i) => ({ json: { chat_id: chatId, text: esc(c), part: i + 1, parts: chunks.length } }));

const clean = (s) => String(s ?? '')
  .replace(/bot\d{6,}:[A-Za-z0-9_-]{20,}/g, 'bot***')
  .replace(/eyJ[A-Za-z0-9._-]{20,}/g, 'jwt***')
  .replace(/(apikey|api_key|token|authorization|bearer)["'=: ]+[A-Za-z0-9._-]{12,}/gi, '$1=***')
  .slice(0, 300);
const e = $input.first().json.error || {};
let n = {};
try { n = $('Normalize Message').first().json; } catch (x) { n = {}; }
const node = typeof e.node === 'object' && e.node ? e.node.name : e.node;
return [{ json: {
  update_id: n.update_id ?? 0, chat_id: n.chat_id ?? null,
  stage: clean(node || 'pipeline').slice(0, 80),
  error: clean(e.message || e.description || 'unknown error')
} }];
